+fn candidates(rows: &[Row]) -> Result<DataFrame> {
+    let base = frame(rows, false)?.lazy();
+    let token = frame(rows, true)?.lazy();
+    let mut frames = Vec::new();
+    for (index, columns) in [vec!["name"], vec!["address"], vec!["prefix"], vec!["initial", "surname_prefix"], vec!["token"]].iter().enumerate() {
+        let mut pairs = generate_blocked_pairs(
+            if index == 4 { &token } else { &base },
+            &[BlockingRule::on(columns)], &LinkType::DedupeOnly, "key", None,
+        )?;
+        if index == 3 {
+            for excluded in ["limited", "ltd", "plc", "llp", "company", "inc", "and"] {
+                pairs = pairs.filter(col("surname_l").neq(lit(excluded)));
+            }
+        }
+        frames.push(pairs.filter(col("needs_resolution_l").or(col("needs_resolution_r")))
+            .select([col("key_l"), col("key_r"), col("name_l"), col("name_r"), col("address_l"), col("address_r")]));
+    }
