+
+fn comparisons(model: &Value) -> Result<Vec<Comparison>> {
+    let mut name = ComparisonBuilder::new("name").null_level().exact_match_level()
+        .levenshtein_level(2).else_level().build()?;
+    let mut address = ComparisonBuilder::new("address").null_level().exact_match_level()
+        .else_level().build()?;
+    for (comparison, settings) in [&mut name, &mut address].into_iter()
+        .zip(model["settings"]["comparisons"].as_array().context("comparisons")?) {
+        let levels = settings["comparison_levels"].as_array().context("levels")?;
+        ensure!(levels.len() == comparison.comparison_levels.len(), "comparison shape changed");
+        for (level, parameters) in comparison.non_null_levels_mut().into_iter().zip(&levels[1..]) {
+            level.m_probability = Some(parameters["m_probability"].as_f64().context("m")?);
+            level.u_probability = Some(parameters["u_probability"].as_f64().context("u")?);
+        }
+    }
